withinRange = (stage, pct) => {
      const r = ENGINE_PCT[stage]
      if (!r || !Number.isFinite(pct)) return 0
      const span = r[1] - r[0] || 1
      return Math.max(0, Math.min(1, (pct - r[0]) / span))
    }

