stageWeight = (job, stage, running) => {
          if (stage === 'queued') return 0
          if (running) return STAGE_WEIGHTS[stage] ?? 0
          const ms = timingsOf(job)[stage]
          return Number.isFinite(ms) && ms > 0 ? ms : 0
        }

client.js::stageSegments.source_code:
stageSegments = (job, running) => {
          const rows = stageRows(job)
          const prep = prepareRows(job)
          const cells = []
          let ahead = 0
          for (const r of rows) {
            const w = stageWeight(job, r.stage, running)
            if (w <= 0) continue
            if (!r.done && !r.running && !r.failedStep) { ahead += w; continue }
            if (r.stage === 'prepare' && prep) {
              for (const sub of prep) {
                if (!sub.done && !sub.running) { ahead += w * sub.weight; continue }
                cells.push({
                  key: sub.stage,
                  label: sub.label,
                  weight: w * sub.weight,
                  frac: sub.frac,
                  done: sub.done,
                  running: sub.running,
                  failedStep: false,
                  dur: sub.dur,
                  hue: PREPARE_HUE[sub.stage],
                })
              }
              continue
            }
            cells.push({
              key: r.stage,
              label: stageLabel(r.stage),
              weight: w,
              frac: r.frac,
              done: r.done,
              running: r.running,
              failedStep: r.failedStep,
              dur: timingsOf(job)[r.stage],
              hue: STAGE_HUE[r.stage] ?? 210,
            })
          }
          return el('div', {
            'data-dscw-p-segbar': '', 'data-tone': job.stage,
            title: legendHintOf(job, running),
          },
            cells.map((c) => {
              const state = c.failedStep ? 'failed' : c.running ? 'running' : c.done ? 'done' : 'todo'
              return el('div', {
                key: c.key, 'data-dscw-p-seg': '', 'data-state': state,
                style: { flex: `${c.weight} 0 0`, '--seg-hue': String(c.hue), '--seg-done': `${Math.round(c.frac * 100)}%` },
                title: running
                  ? `${c.label} · ${Math.round(c.frac * 100)}%${c.dur ? ` · ${fmtMs(c.dur)}` : ''}`
                  : `${c.label} · ${fmtMs(c.weight)}`,
              })
            }).concat(ahead > 0
              ? [el('div', { key: '__ahead', 'data-dscw-p-seg-ahead': '', style: { flex: `${ahead} 0 0` } })]
              : []))
        }

client.js::expandPrepareRows.source_code:
expandPrepareRows = (rows, prep) => {
          if (!prep) return rows
          const out = []
          for (const r of rows) {
            if (r.stage !== 'prepare') { out.push(r); continue }
            for (const sub of prep) {
              out.push({ ...sub, stage: sub.stage, expanded: true })
            }
          }
          return out
        }

client.js::stageLegend.source_code:
stageLegend = (job, running) => {
          const prep = prepareRows(job)
          // prepare 展开时，图例也拆成三个子标签（色块色相与带子里那三段一致）；
          // 不展开时就是原来的一格。
          // 与带子同口径：未执行的阶段不列（列出来只有一排 0%，没有信息量）。
          const reached = stageRows(job)
            .filter((r) => stageWeight(job, r.stage, running) > 0)
            .filter((r) => r.done || r.running || r.failedStep)
          const rows = expandPrepareRows(reached, prep).filter((r) => !r.expanded || r.done || r.running)
          // 色块是颜色与阶段之间唯一的绑定：色块色相与上方进度条里那一段完全一致，
          // 所以「哪段是什么」不用去猜——照着色块找同色的段即可。
          return el('div', {
            'data-dscw-p-legend': '',
            title: legendHintOf(job, running),
          },
            rows.map((r) => {
              const state = r.failedStep ? 'failed' : r.running ? 'running' : r.done ? 'done' : 'todo'
              const pct = Math.round(r.frac * 100)
              const dur = r.expanded ? r.dur : timingsOf(job)[r.stage]
              const name = r.expanded ? r.label : stepName(r.stage)
              return el('span', {
                key: r.stage, 'data-state': state,
                style: { '--seg-hue': String(r.expanded ? PREPARE_HUE[r.stage] : (STAGE_HUE[r.stage] ?? 210)) },
                // 终态把百分比降级到悬停：终态全 100%，写出来只是重复。
                title: running
                  ? `${r.expanded ? r.label : stageLabel(r.stage)} · ${tBound(`legendState_${state}`)} · ${pct}%`
                  : `${r.expanded ? r.label : stageLabel(r.stage)} · ${fmtMs(dur ?? 0)}`,
              },
                el('i', { 'data-swatch': '' }),
                `${name} ${running ? `${pct}%` : fmtMs(dur ?? 0)}`)
            }))
        }

client.js::overallPct.source_code:
overallPct = (job) => {
          const idx = ACTIVE_STAGES.indexOf(stageOf(job))
          // partial 是所有阶段都跑完但完整性没成立：进度按 100 显示（活干完了），
          // 由终态标签「部分完成」+ 阻塞原因说明为什么没算完整成功。
          if (idx < 0) return (job.stage === 'done' || job.stage === 'partial') ? 100 : null
          let pct = 0
          for (const r of stageRows(job)) pct += (STAGE_WEIGHTS[r.stage] ?? 0) * r.frac
          return Math.min(99, Math.round(pct * 100))
        }

client.js::poolSummary.source_code:
poolSummary = (list) => {
          // 排队中的进度恒为 0，算进平均会让「最慢」永远是那个还没开始的仓库，
          // 读数反而失去意义——只统计真正在跑的任务，排队数单独报。
          const running = list.filter((j) => stageOf(j) !== 'queued').map((j) => ({ job: j, p: overallPct(j) })).filter((x) => x.p != null)
          const queuedCount = list.length - running.length
          if (!running.length) return tBound('poolAllQueued').replace('{n}', String(list.length))
          const avg = Math.round(running.reduce((s, x) => s + x.p, 0) / running.length)
          const slowest = running.reduce((m, x) => (x.p < m.p ? x : m))
          const queuedNote = queuedCount > 0 ? ` · ${tBound('poolQueued')} ${queuedCount}` : ''
          return `${avg}% · ${tBound('poolSlowest')} ${repoName(slowest.job.cwd)} ${slowest.p}%${queuedNote}`
        }

client.js::throughputBadge.source_code:
throughputBadge = (job, sparkOf, rateOf) => {
          if (!ACTIVE_STAGES.includes(stageOf(job))) return null
          if (typeof job.tps === 'number' && job.tps > 0) {
            return el('span', { 'data-dscw-p-badge': '', 'data-tone': 'live' },
              `${job.tps >= 100 ? Math.round(job.tps) : job.tps.toFixed(1)} tok/s`,
              el(Spark, { values: sparkOf(job.id) }))
          }
          if (job.batchSubmittedAt) {
            const st = rateOf(job.id)
            const bp = job.batchProgress
            if (st?.rate > 0 && bp && bp.total > bp.completed) {
              const eta = (bp.total - bp.completed) / st.rate
              return el('span', { 'data-dscw-p-badge': '', 'data-tone': 'live' },
                `${st.rate >= 10 ? Math.round(st.rate) : st.rate.toFixed(1)} ${tBound('perMin')}`,
                ` · ${tBound('etaLabel')} ≈ ${eta >= 1 ? `${Math.ceil(eta)} min` : '<1 min'}`)
            }
            return el('span', { 'data-dscw-p-badge': '', 'data-tone': 'live' },
              `${tBound('batchRunLabel')} ${fmtMs(Date.now() - Date.parse(job.batchSubmittedAt))}`)
          }
          return null
        }

