function isLoopbackRequest(req) {
  const addr = String(req?.socket?.remoteAddress ?? '')
  return addr === '127.0.0.1' || addr === '::1' || addr === '::ffff:127.0.0.1'
}

index.js::writeJson.source_code:
function writeJson(res, code, obj) {
  const body = JSON.stringify(obj)
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body) })
  res.end(body)
}

index.js::readBodyJson.source_code:
function readBodyJson(req) {
  return new Promise((resolve, reject) => {
    const chunks = []
    let size = 0
    req.on('data', (c) => {
      size += c.length
      if (size > 1024 * 1024) {
        reject(new Error('请求体超过 1MB'))
        req.destroy()
        return
      }
      chunks.push(c)
    })
    req.on('end', () => {
      try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}')) } catch (err) { reject(err) }
    })
    req.on('error', reject)
  })
}

index.js::listModelCatalog.source_code:
async function listModelCatalog(llm) {
  if (!llm || typeof llm.listProviders !== 'function') {
    return { ok: false, error: 'llm 服务未注入，无法枚举模型提供商；可在设置里手填 batchProvider/batchModel', providers: [] }
  }
  const providers = []
  for (const p of llm.listProviders() ?? []) {
    const id = String(p?.id ?? p?.provider ?? '')
    if (!id) continue
    const entry = { id, name: String(p?.displayName ?? p?.name ?? id), models: [] }
    try {
      if (typeof llm.listModels === 'function') {
        entry.models = (await llm.listModels(id) ?? [])
          .map((m) => ({ id: String(m?.id ?? ''), name: String(m?.name ?? m?.id ?? '') }))
          .filter((m) => m.id)
      }
    } catch (err) {
      entry.error = String(err?.message ?? err)
    }
    providers.push(entry)
  }
  return { ok: true, providers }
}

