function normChangePath(p) {
  const raw = String(p ?? '').replace(/\\/g, '/').trim()
  if (!raw) return null
  if (raw.startsWith('/') || /^[A-Za-z]:/.test(raw)) return null
  const norm = raw.replace(/^\.\//, '')
  if (norm.startsWith('../') || norm.includes('/../') || norm === '..') return null
  return norm
}

