async function waitForDeath(pid, timeoutMs) {
  const deadline = Date.now() + timeoutMs
  const step = 25
  while (Date.now() < deadline) {
    if (!isAlive(pid)) return true
    await new Promise((r) => setTimeout(r, step))
  }
  return !isAlive(pid)
}

