function missingLinksOf(text, source, knownSet) {
  const base = posix(path.posix.dirname(posix(source)))
  const stripped = stripCode(String(text ?? ''))
  const out = new Set()
  const add = (target, bare) => {
    if (isExternalTarget(target)) return
    const candidates = bare ? [target, `${target}.md`] : [target]
    const resolvedList = candidates.map((t) => posix(path.posix.normalize(
      path.posix.join(base === '.' ? '' : base, t),
    )))
    // 任一写法命中已知页就算有效（`core` 与 `core.md` 指的是同一篇）
    if (resolvedList.some((r) => knownSet.has(r))) return
    const first = resolvedList[0]
    if (first.startsWith('../')) return
    out.add(first.endsWith('.md') ? first : `${first}.md`)
  }
  for (const m of scanPageLinks(stripped)) add(m.target, false)
  for (const m of stripped.matchAll(/\[\[([^\]|#]+)(?:[|#][^\]]*)?\]\]/g)) {
    add(String(m[1]).trim(), true)
  }
  return [...out].sort()
}

