class _ProtocolOnly:
    """sys.stdout 的替身：只允许本入口的协议写出走真 stdout，其余一律改道 stderr。

    为什么连 ``flush`` 也要转：FSoft 的进度条会 flush，若 flush 打到真 stdout
    就会把半行日志挤进协议流中间。
    """

    def write(self, text):
        if text:
            try:
                sys.stderr.write(text)
            except Exception:
                pass
        return len(text or "")

    def flush(self):
        try:
            sys.stderr.flush()
        except Exception:
            pass

    def isatty(self):
        return False

    def fileno(self):
        # 有些库会拿 fileno 去判断是否终端；给它 stderr 的句柄，避免抛错。
        return sys.stderr.fileno()

    @property
    def encoding(self):
        return "utf-8"

def write(self, text):
