def detail_suffix():
    """当前正在处理的模块名，拼进进度帧 message；没有就返回空串。

    措辞按阶段分开：阶段 3 是真在写文章（「正在写 X」），阶段 2 是在聚类
    （「正在聚类 X」）。混用会让人以为阶段 2 已经在产出文章，反而更误导。
    """
    try:
        module = _DETAIL["module"]
        phase = _DETAIL["phase"]
        if phase in ("parse", "parse-start"):
            done = _DETAIL["parsed"]
            total = _DETAIL["parsed_total"]
            if total <= 0:
                return ""
            return f"，已解析 {done}/{total} 个源文件"
        if not module:
            if phase == "overview":
                return "，正在生成仓库总览"
            if phase == "super-group":
                return "，正在做子系统归并"
            return ""
        if len(module) > _DETAIL_MAX_LEN:
            module = module[: _DETAIL_MAX_LEN - 3] + "..."
        if phase == "cluster":
            return f"，正在聚类 {module}"
        if phase == "super-group":
            return f"，正在归并 {module}"
        return f"，正在写 {module}"
    except Exception:  # noqa: BLE001
        return ""

