function titleOf(bodyText, fallback) {
  for (const line of String(bodyText ?? '').split(/\r?\n/)) {
    const m = line.match(/^#\s+(.+?)\s*$/)
    if (m) return oneLine(m[1])
  }
  return oneLine(fallback)
}

