function rewritePageLinks(text, pageMap, articleWikiPath, sourcePath = '', { dropUnresolved = false } = {}) {
  const src = String(text ?? '')
  if (!(pageMap instanceof Map) || pageMap.size === 0) return src
  const baseDir = posix(path.posix.dirname(String(articleWikiPath ?? '')))
  // 链接的**解析基准**是引擎源页所在目录，不是落地目录：层级布局下正文写
  // `x_sibling.md`（同目录兄弟）与 `../parent.md`（父级），而落地时页被拍平到
  // .codewiki/modules/ 单层（mapping.js 的 moduleSlug）。按落地目录解析，pageMap
  // 一条都命不中，整篇跨页链接全成死链（真机 Wxxy-CampusLogin 25 条）。
  const sourceDir = posix(path.posix.dirname(String(sourcePath ?? '')))
  // 只在「非代码」区域改写：正文里演示链接写法时用的是行内代码或围栏块，那是语法
  // 示例，改成真实路径反而破坏文档想表达的意思。stripCode 做等长替换，偏移与原文一致。
  const masked = stripCode(src)
  const edits = []
  // 扫描规则来自 wiki-links.js：门、校对、article-contract 共用同一份。分叉的后果是
  // 「门判它是死链、改写器却认不出这条链接」，两边的结论对不上却没人发现。
  for (const m of scanPageLinks(masked)) {
    const { whole, label, anchor: anchorPart } = m
    if (isExternalTarget(m.target)) continue
    const stripped = String(m.target).replace(/^\.\//, '')
    // 先按引擎源目录解析相对路径，再退回「原样名字」——扁平布局（LAYOUT_FLAT）
    // 的链接本来就是根级同名，两种写法都必须能命中。
    const resolved = sourceDir && sourceDir !== '.'
      ? path.posix.normalize(path.posix.join(sourceDir, stripped))
      : stripped
    const landed = pageMap.get(resolved) ?? pageMap.get(stripped)
    if (!landed) {
      // 引擎编造了树中不存在的页名（真机 job-mw0mnr7q-4 的 settings-panel/catalog-ui）。
      // 这种链接落进 wiki 就是点开 404，产品层面必须修掉；但「引擎编造」这个事实
      // 仍由 output.js 的 dead-link 上报，不在渲染期静默丢弃。这里只把语法降级成
      // 纯文字，保留作者写下的链接文字。
      if (dropUnresolved) edits.push({ at: m.index, len: whole.length, text: label })
      continue
    }
    const rel = posix(path.posix.relative(baseDir || '.', landed))
    // 同目录（无斜杠）直接写文件名，与引擎原文风格一致；跨目录补 ./，避免看错层级。
    const href = rel.includes('/') && !rel.startsWith('.') ? './' + rel : rel
    // 命中的链接只替换 `](href)` 这一段：`[文字]` 原样保留，正文措辞一字不动。
    const tail = whole.length - label.length - 1
    edits.push({ at: m.index + label.length + 1, len: tail, text: '](' + href + (anchorPart || '') + ')' })
  }
  // 倒序应用：偏移基于原文，从后往前替换不会互相干扰
  let out = src
  for (let i = edits.length - 1; i >= 0; i -= 1) {
    const e = edits[i]
    out = out.slice(0, e.at) + e.text + out.slice(e.at + e.len)
  }
  return out
}

lib\\engine\\quality-gate.js::renderArti.source_code:
function renderArticle({ article, body, pageMap = null } = {}) {
  const a = article ?? {}
  // 正文只做两类规范化：剥 BOM、把跨页链接改成落地路径。措辞与结构一律不动。
  const raw = String(body ?? '').replace(/^\uFEFF/, '')
  // 指向不存在页面的链接必须降级成纯文字：写进 wiki 的每一条这种链接都是死链，
  // 而它在渲染期是可判定的（pageMap 就是「本次真的会落地」的全集）。引擎编造页名
  // 这件事本身仍由 output.js 的 dead-link 如实上报，不在这里静默吞掉。
  const text = rewritePageLinks(raw, pageMap, a.wikiPath ?? '', a.source ?? '', { dropUnresolved: true })
  const title = titleOf(text, a.moduleName ?? a.source ?? 'untitled')
  const type = String(a.type ?? 'module')
  const sources = Array.isArray(a.sourceFiles) ? a.sourceFiles.map(posix).filter(Boolean) : []
  const lines = ['---', `title: ${yamlScalar(title)}`, `type: ${yamlScalar(type)}`]
  if (sources.length) {
    lines.push('source_files:')
    for (const s of sources) lines.push(`  - ${yamlScalar(s)}`)
  } else {
    // 空列表要显式写出来：省略这个字段会让 downstream 以为「没声明」而不是「声明为空」。
    lines.push('source_files: []')
  }
  // 列表形态与 `[a, b]` 形态都要能过 serde_yaml；用空列表最不易出错。
  lines.push('tags: []')
  lines.push('generated_by: fsoft-native')
  if (a.source) lines.push(`fsoft_page: ${yamlScalar(posix(a.source))}`)
  // 结束标记后**不插空行**：parseFrontmatter 会把空行算进 body，于是「正文一字不动」
  // 就变成「正文 = 原文，但前面多一个换行」——逐字比对永远对不上，而这条正是
  // 「wiki 里这篇 = 引擎产出的那篇」唯一可验证的形式。frontmatter 紧接正文是合法
  // markdown（Jekyll/Hugo 同样接受，serde_yaml 的 parse_frontmatter 也按行切）。
  lines.push('---')
  return `${lines.join('\n')}\n${text}`
}

