lib\\git-paths.js::decodeGitPath.source_code:
function decodeGitPath(p) {
  const s = String(p ?? '')
  if (s.length < 2 || !s.startsWith('"') || !s.endsWith('"')) return s
  const inner = s.slice(1, -1)
  const bytes = []
  for (let i = 0; i < inner.length; i += 1) {
    const ch = inner[i]
    if (ch === '\\') {
      const next = inner[i + 1]
      if (next !== undefined && next >= '0' && next <= '7') {
        const oct = inner.slice(i + 1, i + 4)
        if (/^[0-7]{3}$/.test(oct)) {
          bytes.push(parseInt(oct, 8))
          i += 3
          continue
        }
      }
      if (next !== undefined && Object.prototype.hasOwnProperty.call(SIMPLE_ESCAPES, next)) {
        bytes.push(SIMPLE_ESCAPES[next])
        i += 1
        continue
      }
      // 不认识的转义：保留反斜杠本体，不猜
      bytes.push(0x5c)
      continue
    }
    const cp = ch.codePointAt(0)
    if (cp < 0x80) {
      bytes.push(cp)
    } else {
      for (const b of Buffer.from(ch, 'utf8')) bytes.push(b)
    }
    if (cp > 0xffff) i += 1 // 代理对：跳过低半区
  }
  return Buffer.from(bytes).toString('utf8')
}

