function adoptOrphan(job, { instanceId, now = Date.now() }) {
  const iso = new Date(now).toISOString()
  job.owner = instanceId
  job.ownerAdoptedAt = iso
  job.heartbeatAt = iso
  job.updatedAt = iso
  return job
}

