function findActiveJob(jobs, cwd, { keyOf = normKey } = {}) {
  const key = keyOf(cwd)
  let best = null
  for (const j of jobs) {
    if (isTerminalStage(j.stage)) continue
    if (keyOf(j.cwd) !== key) continue
    if (!best || String(j.createdAt ?? '').localeCompare(String(best.createdAt ?? '')) > 0) best = j
  }
  return best
}

