function loadUpdateRecord(wikiPath, fsImpl = fs) {
  try {
    const raw = fsImpl.readFileSync(recordPath(wikiPath), 'utf8')
    const rec = JSON.parse(raw)
    if (rec?.version !== UPDATE_RECORD_VERSION) return null
    return rec
  } catch {
    return null
  }
}

