pub fn parse(content: &str) -> Result<Option<ArticleFrontmatter>> {
    let content = content.trim();
    if !content.starts_with("---") {
        return Ok(None);
    }

    let rest = &content[3..];
    let end = rest.find("\n---");
    match end {
        Some(pos) => {
            let yaml = &rest[..pos];
            let fm: ArticleFrontmatter = serde_yaml::from_str(yaml)?;
            Ok(Some(fm))
        }
        None => Ok(None),
    }
}

